package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.CountingOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarArchiveOutputStream_write_TriageGen2Test {

    private ByteArrayOutputStream out;
    private TarArchiveOutputStream tarOut;
    private static final int BLOCK_SIZE = 512;

    @Before
    public void setUp() throws IOException {
        out = new ByteArrayOutputStream();
        tarOut = new TarArchiveOutputStream(out, BLOCK_SIZE);
    }





    @Test
    public void testWriteSmallChunkAssembling() throws IOException {
        int size = BLOCK_SIZE;
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(size);
        tarOut.putArchiveEntry(entry);

        byte[] data = new byte[size];
        // Write in three small chunks to trigger assemLen logic
        int chunk1 = 100;
        int chunk2 = 200;
        int chunk3 = size - chunk1 - chunk2;

        tarOut.write(data, 0, chunk1);
        tarOut.write(data, 0, chunk2);
        tarOut.write(data, 0, chunk3);

        tarOut.closeArchiveEntry();
        tarOut.finish();

        // The bytes should be written to the underlying stream eventually
        // Note: Depending on internal implementation of writeRecord, 
        // it might not flush to 'out' until a full block is reached.
        Assert.assertTrue(out.size() >= size);
    }






}

package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.CountingOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarArchiveOutputStream_write_TriageGen2Test {

    private ByteArrayOutputStream out;
    private TarArchiveOutputStream tarOut;
    private static final int BLOCK_SIZE = 512;

    @Before
    public void setUp() throws IOException {
        out = new ByteArrayOutputStream();
        tarOut = new TarArchiveOutputStream(out, BLOCK_SIZE);
    }







    @Test
    public void testWriteTriggersAssembleBufferFlush() throws IOException {
        // This tests the branch: if ((assemLen + numToWrite) >= recordBuf.length)
        int size = BLOCK_SIZE * 2;
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(size);
        tarOut.putArchiveEntry(entry);

        byte[] data = new byte[size];

        // 1. Fill assemBuf partially
        tarOut.write(data, 0, BLOCK_SIZE - 10); 

        // 2. Write enough to trigger the (assemLen + numToWrite) >= recordBuf.length branch
        // This will copy assemBuf to recordBuf, then copy current wBuf to recordBuf, then writeRecord
        tarOut.write(data, 0, 20); 

        // 3. Write remaining
        tarOut.write(data, 0, size - (BLOCK_SIZE - 10 + 20));

        tarOut.closeArchiveEntry();
        tarOut.finish();

        Assert.assertTrue(out.size() >= size);
    }




}

package org.apache.commons.compress.archivers.tar;

import java.io.*;
